/** Bundled images so Vercel serverless never depends on the public/ folder. */
export const CHAPEL_LOGO_PNG = Buffer.from("", "base64");

export const AVATAR_JPEG: Record<string, Buffer> = {
  "01": Buffer.from("", "base64"),
  "02": Buffer.from("", "base64"),
  "03": Buffer.from("", "base64"),
  "04": Buffer.from("", "base64"),
  "05": Buffer.from("", "base64"),
  "06": Buffer.from("", "base64"),
  "07": Buffer.from("", "base64"),
  "08": Buffer.from("", "base64"),
};

export function embeddedFile(relPath: string): { data: Buffer; mime: string } | null {
  const p = relPath.replace(/^\/+/, "").replace(/\\/g, "/");
  if (p === "brand/logo.png" || p === "brand/act-of-faith-logo.png" || p === "chapel-logo.png" || p === "samples/ministry-logo.png") {
    return { data: CHAPEL_LOGO_PNG, mime: "image/png" };
  }
  const m = p.match(/^(?:avatars\/)?(\d{2})\.jpe?g$/i);
  if (m && AVATAR_JPEG[m[1]]) return { data: AVATAR_JPEG[m[1]], mime: "image/jpeg" };
  return null;
}
